    table: { head: ["", "parler", "finir", "vendre"], rows: [["je", "ai parl**é**", "ai fin**i**", "ai vend**u**"], ["tu", "as parl**é**", "as fin**i**", "as vend**u**"], ["il/elle/on", "a parl**é**", "a fin**i**", "a vend**u**"], ["nous", "avons parl**é**", "avons fin**i**", "avons vend**u**"], ["vous", "avez parl**é**", "avez fin**i**", "avez vend**u**"], ["ils/elles", "ont parl**é**", "ont fin**i**", "ont vend**u**"]] },
