    table: { head: ["", "parler", "être", "pouvoir"], rows: [["je", "parler**ais**", "ser**ais**", "pourr**ais**"], ["tu", "parler**ais**", "ser**ais**", "pourr**ais**"], ["il/elle/on", "parler**ait**", "ser**ait**", "pourr**ait**"], ["nous", "parler**ions**", "ser**ions**", "pourr**ions**"], ["vous", "parler**iez**", "ser**iez**", "pourr**iez**"], ["ils/elles", "parler**aient**", "ser**aient**", "pourr**aient**"]] },
