    ex: [["J'[[aurais aimé]] te voir.", "Me habría gustado verte."], ["Elle [[serait venue]] avec plaisir.", "Habría venido con gusto."], ["Tu [[aurais dû]] me le dire.", "Debiste decírmelo."]],
